'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={boot:null,exam:null,card:0,stage:0,dirty:false,job:null,provider:localStorage.getItem('qm-provider')||'codex',model:localStorage.getItem('qm-model')||'',standards:{},authoringDraft:null};
const labels=['문항카드','문항 작성','자료 그림','검토 · 출력'];
let toastTimer,pollTimer,jobWatchId=null,jobWatchToken=0,jobPollErrors=0,jobProgressDismissed=false;
const uxModeSwitch=$('#uxModeSwitch');
if(uxModeSwitch&&new URLSearchParams(location.search).get('ux')==='old'){
 uxModeSwitch.href='/?ux=new';uxModeSwitch.textContent='새 화면 보기';uxModeSwitch.setAttribute('aria-label','새 출제 화면으로 전환');
}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,7000)}
async function api(path,data){if(data?.exam_id&&data.exam_id===state.exam?.id&&data.revision===undefined)data.revision=state.exam.revision;const response=await fetch(path,data?{method:'POST',headers:{'Content-Type':'application/json','X-Studio-Token':state.boot.token},body:JSON.stringify(data)}:{});const value=await response.json();if(!response.ok){const error=new Error(value.error||'요청에 실패했습니다.');error.status=response.status;error.code=value.code||null;error.details=value.details||null;throw error}return value}
async function action(fn){try{await fn()}catch(e){toast(e.message)}}
const previewMathCache=new Map(),previewMathPending=new Map();let previewMathTimer=null;
function previewMathText(value){const text=String(value??'');return `<span class="preview-math-source" data-preview-text="${esc(text)}">${esc(text)}</span>`}
function previewNeedsMath(value){return /\$\$[\s\S]+?\$\$|\$[^$\r\n]+\$|\\\([\s\S]+?\\\)|\\\[[\s\S]+?\\\]|(^|[^A-Za-z0-9_/])[A-Za-z]{1,3}(?:_(?:\{[A-Za-z0-9+\-]+\}|[A-Za-z0-9])|\^(?:\{[A-Za-z0-9+\-]+\}|[A-Za-z0-9]))(?=$|[^A-Za-z0-9_/])/.test(String(value||''))}
function previewMathMarkup(segments,source){
 if(!Array.isArray(segments))return esc(source);
 return segments.map(segment=>{
  if(segment?.type==='math'&&typeof segment.url==='string'&&segment.url.startsWith('/label-assets/')){
   const width=Math.max(1,Math.min(1600,Number(segment.width)||20)),height=Math.max(1,Math.min(800,Number(segment.height)||20));
   return `<img class="preview-math-image" src="${esc(segment.url)}" width="${width}" height="${height}" alt="${esc(segment.text||'수식')}">`;
  }
  return esc(segment?.text??'');
 }).join('');
}
function applyPreviewMath(source,segments){
 for(const node of document.querySelectorAll('#previewSheet .preview-math-source'))if(node.dataset.previewText===source){node.innerHTML=previewMathMarkup(segments,source);node.dataset.previewMathReady='true';node.removeAttribute('title')}
}
function showApprovalDiscrepancy(details){
 const dialog=$('#approvalDiscrepancyDialog'),kind=details?.kind,title=kind==='calculation'?'계산식 검산 결과가 일치하지 않습니다.':kind==='image'?'그림 제약 검사 결과가 일치하지 않습니다.':'승인 전 확인 결과가 일치하지 않습니다.',
  canOverride=['calculation','image'].includes(kind)&&typeof details?.validation_digest==='string'&&details.validation_digest.length>0,
  rows=Array.isArray(details?.checks)?details.checks:[],checks=rows.length?`<div class="approval-discrepancy-list">${rows.map(item=>`<div class="check-result ${item.ok?'':'fail'}"><b>${esc(item.label||'검사')}</b> · ${item.ok?'일치':`불일치${item.detail?` · ${esc(item.detail)}`:''}`}</div>`).join('')}</div>`:'<div class="check-result fail">불일치 항목의 상세 결과가 없습니다.</div>';
 dialog.innerHTML=`<div class="dialog-top"><div><div class="eyebrow">승인 전 확인</div><h2>${esc(title)}</h2></div><button class="icon-btn" type="button" data-approval-choice="cancel" aria-label="검토로 돌아가기">×</button></div><p role="alert">${kind==='calculation'?'계산식의 검산 결과를 확인해 주세요.':kind==='image'?'그림의 제약 검사 결과를 확인해 주세요.':'서버가 승인 보류 사유를 반환했습니다.'} 선택하기 전에는 승인되지 않습니다.</p>${checks}<div class="notice warn">${canOverride?'결과를 확인한 뒤 승인하거나 검토를 취소할 수 있습니다. 그래도 승인하면 이번 문항 또는 그림의 현재 검사 결과를 승인 기록에 함께 저장합니다.':'이 응답에는 예외 승인에 필요한 검증 정보가 없습니다. 검토를 계속해 주세요.'}</div><div class="dialog-actions"><button type="button" data-approval-choice="cancel">취소하고 검토</button><button type="button" id="confirmDiscrepancyOverride" class="primary" ${canOverride?'':'disabled'}>오류를 확인했고 그래도 승인</button></div>`;
 return new Promise(resolve=>{
  let settled=false;
  const finish=choice=>{if(settled)return;settled=true;dialog.removeEventListener('cancel',onCancel);dialog.close();resolve(choice)};
  const onCancel=event=>{event.preventDefault();finish(false)};
  dialog.addEventListener('cancel',onCancel);
  dialog.querySelectorAll('[data-approval-choice="cancel"]').forEach(button=>button.onclick=()=>finish(false));
  const approve=dialog.querySelector('#confirmDiscrepancyOverride');if(approve)approve.onclick=()=>finish(canOverride);
  dialog.showModal();
 });
}
async function approveWithDiscrepancy(card,kind,materialId=null){
 const request={exam_id:state.exam.id,card_id:card.id,kind,approved:true};if(kind==='image'&&materialId)request.material_id=materialId;
 try{return await api('/api/approve',request)}catch(error){
  const details=error?.details;if(error?.code!=='approval_discrepancy'||!details)throw error;
  const canOverride=['calculation','image'].includes(details.kind)&&typeof details.validation_digest==='string'&&details.validation_digest.length>0;
  const proceed=await showApprovalDiscrepancy(details);if(!proceed){toast('승인을 취소했습니다. 검사 결과를 검토한 뒤 다시 진행할 수 있습니다.');return null}
  if(!canOverride)throw error;
  return await api('/api/approve',{...request,override:{kind:details.kind,validation_digest:details.validation_digest}});
 }
}
function renderPreviewMath(){
 clearTimeout(previewMathTimer);
 previewMathTimer=setTimeout(async()=>{
  const sources=[...new Set([...document.querySelectorAll('#previewSheet .preview-math-source')].map(node=>node.dataset.previewText||'').filter(previewNeedsMath))];
  await Promise.allSettled(sources.map(async source=>{
   const cached=previewMathCache.get(source);if(cached){applyPreviewMath(source,cached);return}
   let request=previewMathPending.get(source);
   if(!request){request=api('/api/math-preview',{text:source}).then(result=>{if(!Array.isArray(result.segments))throw new Error('수식 미리보기 응답 형식이 올바르지 않습니다.');previewMathCache.set(source,result.segments);if(previewMathCache.size>250)previewMathCache.delete(previewMathCache.keys().next().value);return result.segments});previewMathPending.set(source,request)}
   try{applyPreviewMath(source,await request)}catch{for(const node of document.querySelectorAll('#previewSheet .preview-math-source'))if(node.dataset.previewText===source)node.title='수식 미리보기를 불러오지 못했습니다.'}
   finally{if(previewMathPending.get(source)===request)previewMathPending.delete(source)}
  }));
 },100);
}
async function boot(){state.boot=await api('/api/bootstrap');state.standards=await api('/api/standards');renderSidebar();render();}
function renderSidebar(){const subjectSelect=$('#createForm').elements.subject;const previousSubject=subjectSelect.value;subjectSelect.innerHTML='<option value="">과목을 선택해 주세요</option>'+state.boot.subjects.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(x.id)} (${x.count}개 기준)</option>`).join('');subjectSelect.value=previousSubject;$('#examList').innerHTML=state.boot.exams.map(e=>`<button class="${state.exam?.id===e.id?'active':''}" data-exam="${e.id}">${esc(e.title)}<small>${esc(e.updated.slice(0,10))} · 출제 작업</small></button>`).join('');const src=$('#createForm').elements.source;src.innerHTML='<option value="blank">빈 문항카드로 시작</option><option value="upload">문항카드 엑셀 가져오기</option>'+state.boot.legacy.map((e,i)=>`<option value="legacy:${i}">기존 회차 · ${esc(e.split('/')[1])}</option>`).join('')}
async function openExam(id){await save();state.exam=await api('/api/exams/'+id);state.card=0;state.stage=0;state.dirty=false;renderSidebar();render();if(state.exam.active_job)watch(state.exam.active_job)}
async function save(){if(!state.exam||!state.dirty)return;state.exam=await api('/api/save',{exam_id:state.exam.id,revision:state.exam.revision,title:state.exam.title,subject:state.exam.subject,cards:state.exam.cards});state.dirty=false;const el=$('#saveState');if(el)el.textContent='저장됨';}
function current(){return state.exam?.cards[state.card]}
function badge(c){const status=authoringStatus(c);return `<span class="badge ${status==='검토 완료'?'success':status==='검토 대기'?'warn':status==='AI 생성 대기'?'ai-pending':'dim'}">${esc(status)}</span>`}
function render(){const e=state.exam;$('#examTitle').textContent=e?.title||'아이디어가 시험지가 되는 곳';$('#crumbTitle').textContent=e?.title||'시작하기';$('#subtitle').textContent=e?'교사의 아이디어를 바탕으로 문항과 그림을 다듬고, 학교 양식으로 완성하세요.':'문항카드, 자료 그림, 학교 양식 출력을 하나의 흐름으로 연결합니다.';$('#topActions').innerHTML=e?'<span class="saved" id="saveState">저장됨</span><button class="quiet danger" id="deleteExam">작업실 삭제</button><button id="saveBtn">저장</button><button class="primary" id="runAll">✧ Yes 문항 일괄 생성</button>':'';$('#steps').innerHTML=labels.map((x,i)=>`<button class="step ${state.stage===i?'active':''}" data-stage="${i}" ${e?'':'disabled'}><span class="num">0${i+1}</span><span>${x}<small>${['입력 · 성취기준 · 아이디어','문두 · 발문 · 보기 · 해설','선화 생성 · 미리보기 · 승인','검산 · 시험지 · 답지'][i]}</small></span></button>`).join('');$('#approvalBar').innerHTML=e?approvalBar():'';$('#workspace').innerHTML=!e?welcome():state.stage===0&&state.authoringDraft?.mode?authoringDraftView():[overview,editor,imageEditor,exportsView][state.stage]();bindWorkspace();renderStats();renderPreviewMath();bindReorder();if(typeof initLayers==='function')initLayers();if(typeof initImageFlow==='function')initImageFlow();if(state.job?.status==='running')setBusy(true)}
function welcome(){return `<section class="welcome"><div><div class="eyebrow">FROM IDEA TO EXAM</div><h2>선생님의 출제 의도에,<br>완성도 있는 문항을 더합니다.</h2><p>성취기준과 핵심 아이디어만 준비해 주세요.<br>문항 생성부터 과학 선화, 학교 양식 시험지와 해설까지 같은 작업실에서 이어집니다.</p><button class="primary" id="startWelcome">첫 시험 만들기 →</button></div><div class="paper-art"><div class="paper-mini"><div class="eyebrow">PHYSICS · ASSESSMENT</div><h3>역학과 에너지</h3><div class="line"></div><div class="line short"></div><div class="box">F →　▱　→ v</div><div class="line"></div><div class="line short"></div><div class="line"></div><span class="badge success">문항 · 자료 · 해설</span></div></div></section><div class="stats"><div class="stat"><span>01 / 문항카드</span><strong>출제 의도<small>입력</small></strong></div><div class="stat"><span>02 / CLI 작업</span><strong>문항·해설<small>생성</small></strong></div><div class="stat"><span>03 / 과학 선화</span><strong>자료 그림<small>검토</small></strong></div><div class="stat"><span>04 / 학교 양식</span><strong>시험지<small>완성</small></strong></div></div>`}
function approvalBar(){const e=state.exam,approved=!!e.card_approval;return `<div class="approval-bar"><div><b>${approved?'✓ 문항카드 전체 승인 완료':'문항카드 검토 → 승인 → 그림 제작 → 시험지 출력'}</b><small>${approved?'이제 실제 그림을 생성하고 승인한 뒤 시험지를 출력할 수 있습니다.':'문항 번호 1~'+e.cards.length+'번 · 상·중·하별 100점 배점과 문항 내용을 확인한 후 승인하세요.'}</small></div><div class="buttons-wrap">${approved?'<button id="generateAllImages" class="primary">전체 자료 그림 생성</button>':''}<button id="allocatePoints" class="small-btn">100점 자동 배점</button><button id="approveCards" class="${approved?'secondary':'primary'}" ${approved?'disabled':''}>${approved?'승인 완료':'문항카드 전체 승인'}</button></div></div>`}
function answerNumber(answer){const value=String(answer??'').trim(),circled='①②③④⑤';if(/^[1-5]$/.test(value))return circled[Number(value)-1];return value.length===1&&circled.includes(value)?value:value||'미입력'}
function authoringHasContent(card){return !!card&&['standard','type','difficulty','idea','stem','material','question','statements','choices','answer','concepts','explanation','points'].some(key=>String(card[key]??'').trim())}
function authoringIsPristine(card){return !!card&&(!card.authoring_mode||card.authoring_mode==='legacy')&&!authoringHasContent(card)&&card.data_kind==='none'&&!card.review_approved&&!card.image&&!card.image_scene&&(!Array.isArray(card.materials)||card.materials.length===0)&&!card.calculation&&!(card.checks||[]).length}
function authoringAiPending(card){return !!card?.ai_requested&&!authoringIsPristine(card)}
function authoringStatus(card){if(card?.review_approved)return '검토 완료';if(authoringAiPending(card))return 'AI 생성 대기';if(String(card?.question||'').trim())return '검토 대기';if(card?.authoring_mode==='manual'||authoringHasContent(card))return '직접 작성 중';return '작성 전'}
function authoringDraftKey(examId=state.exam?.id){return examId?`qm-authoring-draft:${examId}`:null}
function authoringPersistLocal(){const session=state.authoringDraft,key=authoringDraftKey();if(!session||!key)return;try{localStorage.setItem(key,JSON.stringify({exam_id:state.exam.id,session}))}catch{}}
function authoringClearLocal(examId=state.exam?.id){const key=authoringDraftKey(examId);if(key)try{localStorage.removeItem(key)}catch{}}
function authoringChoose(mode){const backup=state.authoringChoiceBackup;$('#authoringChoiceDialog')?.close();if(backup&&!window.confirm('저장하지 않은 임시 문항이 있습니다. 확인하면 이 초안을 삭제하고 새 문항을 시작합니다.')){state.authoringDraft=backup;state.authoringChoiceBackup=null;render();return}if(backup){state.authoringDraft=backup;authoringDiscard()}else state.authoringDraft=null;state.authoringChoiceBackup=null;authoringStart(mode)}
function authoringRestoreLocal(examId){try{const value=JSON.parse(localStorage.getItem(authoringDraftKey(examId))||'null');if(value?.exam_id===examId&&value.session?.mode&&value.session.draft){state.authoringDraft=value.session;state.authoringDraft.suspended=true;state.stage=0;return true}}catch{}return false}
function authoringBlankCard(id='',no=1){return {id,no,standard:'',standard_name:'',standard_note:'',difficulty:'',type:'',idea:'',stem:'',material:'',question:'',statements:'',choices:'',points:'',concepts:'',explanation:'',review_note:'',image_mode:'',image_locked:'',image_creative:'',ai_feedback:'',image_text_physics:'',image_text_math:'',image_text_korean:'',image_text_none:false,image_plan_version:2,image_plan_approval:null,image_labels:[],labels_initialized:false,image_scene:null,answer:'',estimate:'',discrimination:'',original_no:'',data_kind:'none',calculation:false,checks:[],calculation_override:null,review_approved:false,image:null,ai_requested:false,materials:null,materials_request:'',material_request_kinds:[],material_request_image_mode:'',authoring_mode:'legacy'} }
function authoringFirstBlankId(){return state.exam?.cards?.length===1&&authoringIsPristine(state.exam.cards[0])?state.exam.cards[0].id:null}
function authoringSelect(key,label,options,draft,full=false){return `<label class="${full?'full':''}">${label}<select data-authoring-field="${key}">${options.map(([value,text])=>`<option value="${esc(value)}" ${String(draft[key]??'')===String(value)?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`}
function authoringCoreFields(draft){const standards=Object.entries(state.standards||{}).filter(([,v])=>v.subject===state.exam?.subject).map(([code,v])=>[code,`${code} · ${v.name}`]);if(draft.standard&&!standards.some(([code])=>code===draft.standard))standards.unshift([draft.standard,`${draft.standard} · 과목 확인 필요`]);return `<fieldset class="authoring-group full"><legend>출제 기준</legend><div class="fields"><label class="full">성취기준 · ${esc(subjectLabel())}<select data-authoring-field="standard"><option value="">성취기준 선택</option>${standards.map(([code,text])=>`<option value="${esc(code)}" ${draft.standard===code?'selected':''}>${esc(text)}</option>`).join('')}</select></label>${authoringSelect('type','문항 유형',[['','선택해 주세요'],...(state.boot?.types||[]).map(v=>[v,v])],draft)}${authoringSelect('difficulty','난이도',[['','선택해 주세요'],['하','하'],['중','중'],['상','상']],draft)}<label class="full">문항 핵심 아이디어<textarea data-authoring-field="idea" placeholder="물리 상황과 평가할 개념을 적어 주세요.">${esc(draft.idea||'')}</textarea></label></div><p class="hint" data-authoring-standard-note>${esc(draft.standard_name||'성취기준을 선택해 주세요.')}</p></fieldset>`}
const authoringRequestKindOptions=[['image','그림'],['text','글상자'],['table','표']];
function authoringRequestKinds(draft){const selected=Array.isArray(draft?.material_request_kinds)?draft.material_request_kinds:[];return authoringRequestKindOptions.map(([kind])=>kind).filter(kind=>selected.includes(kind))}
function authoringRequestImageModeDisabled(draft){const kinds=authoringRequestKinds(draft);return kinds.length>0&&!kinds.includes('image')}
function authoringSetRequestKinds(draft,kinds){const selected=new Set(Array.isArray(kinds)?kinds:[]);draft.material_request_kinds=authoringRequestKindOptions.map(([kind])=>kind).filter(kind=>selected.has(kind));if(authoringRequestImageModeDisabled(draft))draft.material_request_image_mode=''}
function authoringSyncRequestImageMode(form,draft){const select=form?.querySelector('[data-authoring-field="material_request_image_mode"]');if(select){select.disabled=authoringRequestImageModeDisabled(draft);select.value=draft.material_request_image_mode||''}}
function authoringRequestControls(draft){const selected=authoringRequestKinds(draft),disabled=authoringRequestImageModeDisabled(draft);return `<div class="authoring-request-types"><span id="authoringRequestKindsLabel">필요한 자료 유형</span><div class="authoring-request-kinds" role="group" aria-labelledby="authoringRequestKindsLabel">${authoringRequestKindOptions.map(([kind,label])=>`<label><input type="checkbox" data-authoring-request-kind="${kind}" ${selected.includes(kind)?'checked':''}>${label}</label>`).join('')}</div></div><label class="authoring-request-image-mode">그림 유형<select data-authoring-field="material_request_image_mode" aria-describedby="authoringRequestImageModeHint" ${disabled?'disabled':''}><option value="" ${!draft.material_request_image_mode?'selected':''}>AI 판단</option><option value="strict" ${draft.material_request_image_mode==='strict'?'selected':''}>strict · SVG 고정만</option><option value="mixed" ${draft.material_request_image_mode==='mixed'?'selected':''}>mixed · SVG 고정 + 창작 분리</option><option value="flexible" ${draft.material_request_image_mode==='flexible'?'selected':''}>flexible · 창작만</option></select></label><p id="authoringRequestImageModeHint" class="hint authoring-request-hint">strict는 고정 SVG만, flexible은 창작 요소만 씁니다. mixed는 두 영역에 서로 다른 요소를 지정합니다. 그림에 글씨를 넣어 달라고 요청하지 마세요.</p>`}
function authoringDraftView(){const session=state.authoringDraft,draft=session?.draft;if(!session?.mode||!draft)return overview();const isAi=session.mode==='ai';const materialFields=typeof uxCanonicalMaterialsEditor==='function'?uxCanonicalMaterialsEditor(draft):`<section class="material-manager full"><div class="material-manager-head"><div><h3>자료</h3><p>필요한 그림·글상자·표를 입력합니다.</p></div></div><label class="full">자료 종류<select data-authoring-field="data_kind">${[['none','자료 없음'],['image','그림'],['text','글상자'],['table','표']].map(([value,label])=>`<option value="${value}" ${draft.data_kind===value?'selected':''}>${label}</option>`).join('')}</select></label>${draft.data_kind!=='none'?`<label class="full">${draft.data_kind==='image'?'그림 장면 설명':draft.data_kind==='table'?'자료 표 · 마크다운':'자료 글상자'}<textarea data-authoring-field="material" class="tall">${esc(draft.material||'')}</textarea></label>`:''}</section>`;return `<section class="design-authoring"><div class="authoring-heading"><button type="button" class="small-btn" data-authoring-cancel>← 문항 목록</button><div><div class="eyebrow">${isAi?'AI DRAFT':'MANUAL DRAFT'}</div><h2>${session.targetCardId?`${esc(String(draft.no).padStart(2,'0'))}번 문항`:'새 문항'} · ${isAi?'AI 초안':'직접 작성'}</h2><p>${isAi?'출제 기준과 아이디어를 저장합니다. AI 생성은 저장 후 원할 때 직접 시작합니다.':'입력이 덜 끝난 문항도 초안으로 저장할 수 있습니다.'}</p></div></div><form id="authoringDraftForm" class="authoring-draft-form" novalidate><section class="panel"><div class="panel-body"><div class="authoring-fields">${authoringCoreFields(draft)}${isAi?`<fieldset class="authoring-group full"><legend>자료 요청 <span class="muted">선택 사항</span></legend><label class="full">필요한 자료 요청<textarea data-authoring-field="materials_request" maxlength="4000" placeholder="예: 표로 제시할 측정값, 그림의 간단한 스케치, ㄱ·ㄴ 보기와 연결할 자료를 적어 주세요.">${esc(draft.materials_request||'')}</textarea><small class="hint" id="materialsRequestCount">${Array.from(String(draft.materials_request||'')).length}/4000자</small></label>${authoringRequestControls(draft)}<p class="hint">문항 본문·발문·정답·해설은 생성 후 검토 단계에서 작성합니다.</p></fieldset>`:`<fieldset class="authoring-group full"><legend>문항 구성</legend><div class="fields"><label class="full">문두<textarea data-authoring-field="stem" placeholder="문항에서 제시하는 상황을 적어 주세요.">${esc(draft.stem||'')}</textarea></label><div class="full">${materialFields}</div><label class="full">발문<textarea data-authoring-field="question" placeholder="학생이 답해야 하는 내용을 적어 주세요.">${esc(draft.question||'')}</textarea></label><label class="full">보기 · ㄱ, ㄴ, ㄷ<textarea data-authoring-field="statements" placeholder="필요한 경우 보기 내용을 적어 주세요.">${esc(draft.statements||'')}</textarea></label><label class="full">선택지 · ①~⑤<textarea class="tall" data-authoring-field="choices" placeholder="선택지를 적어 주세요.">${esc(draft.choices||'')}</textarea></label><label>정답 번호 · 1~5<input data-authoring-field="answer" value="${esc(draft.answer||'')}" placeholder="예: 2"></label><label>내용 영역<input data-authoring-field="concepts" value="${esc(draft.concepts||'')}" placeholder="예: 운동량"></label><label class="full">정답·해설<textarea class="tall" data-authoring-field="explanation" placeholder="풀이와 오답 분석을 적어 주세요.">${esc(draft.explanation||'')}</textarea></label></div><label class="check-row"><input type="checkbox" data-authoring-bool="calculation" ${draft.calculation?'checked':''}>계산이 포함된 문항</label><label class="full">검산식 <span class="muted">선택 사항 · 한 줄에 이름 | 왼쪽 식 | 오른쪽 식</span><textarea data-authoring-checks>${esc((draft.checks||[]).map(x=>`${x.label} | ${x.lhs} | ${x.rhs}`).join('\n'))}</textarea></label></fieldset>`}</div></div></section><div class="review-action-dock" id="taskActionBar">${typeof uxState!=='undefined'?uxPrimary():`<div class="task-action"><span>${isAi?'입력한 기준을 저장 대기 목록에 추가합니다.':'초안으로 저장하고 검토 단계에서 계속 편집합니다.'}</span><button type="button" class="secondary" data-authoring-cancel>목록으로 돌아가기</button><button type="submit" class="primary">${isAi?'생성 대기에 추가':'문항 저장'}</button></div>`}</div></form></section>`}
function authoringStart(mode,targetId=null){if(!state.exam)return;const existing=targetId?state.exam.cards.find(card=>card.id===targetId):null,reuseCardId=existing?null:authoringFirstBlankId(),localId='draft_'+(typeof uxMakeId==='function'?uxMakeId():crypto.randomUUID().replaceAll('-','').slice(0,16)),draft=existing?structuredClone(existing):authoringBlankCard(reuseCardId||localId,state.exam.cards.length+1),persistMode=existing?.authoring_mode==='manual'?'manual':mode;if(typeof uxEnsureMaterials==='function'&&mode==='manual')uxEnsureMaterials(draft);state.authoringChoiceBackup=null;state.authoringDraft={examId:state.exam.id,mode,targetCardId:existing?.id||null,persistMode,reuseCardId,draft,committedCardId:null,activePlanMaterialId:null,suspended:false};state.stage=0;authoringPersistLocal();render();requestAnimationFrame(()=>document.querySelector('#authoringDraftForm [data-authoring-field="standard"]')?.focus({preventScroll:true}))}
function authoringOpenChoice(){if(!state.exam)return;if(state.authoringDraft?.mode&&!state.authoringDraft.suspended){toast('현재 문항을 저장하거나 목록으로 돌아가 주세요.');return}state.authoringChoiceBackup=state.authoringDraft?.suspended?state.authoringDraft:null;state.authoringDraft={mode:null,targetCardId:null,reuseCardId:authoringFirstBlankId(),draft:authoringBlankCard('',state.exam.cards.length+1),committedCardId:null};$('#authoringChoiceDialog').showModal()}
function authoringCancel(){const session=state.authoringDraft;$('#authoringChoiceDialog')?.close();if(session?.mode){session.suspended=true;authoringPersistLocal()}else if(state.authoringChoiceBackup){state.authoringDraft=state.authoringChoiceBackup;state.authoringChoiceBackup=null}else{state.authoringDraft=null;authoringClearLocal()}if(state.exam){state.stage=0;render();requestAnimationFrame(()=>$('#addCard, [data-authoring-resume]')?.focus({preventScroll:true}))}}
function authoringDiscard(){const draftId=state.authoringDraft?.draft?.id;if(typeof uxState!=='undefined'&&draftId&&uxState.materialByCard[draftId])delete uxState.materialByCard[draftId];state.authoringDraft=null;state.authoringChoiceBackup=null;authoringClearLocal();if(state.exam){state.stage=0;render();requestAnimationFrame(()=>$('#addCard')?.focus({preventScroll:true}))}}
function authoringProjection(card){const keys=['standard','standard_name','standard_note','type','difficulty','idea','stem','material','question','statements','choices','answer','concepts','explanation','calculation','checks','points','data_kind','materials','image','image_scene','image_mode','image_locked','image_creative','image_text_physics','image_text_math','image_text_korean','image_text_none'];return Object.fromEntries(keys.map(key=>[key,card?.[key]??null]))}
function authoringApplyDraft(){const session=state.authoringDraft;if(!session?.mode||!session.draft||!state.exam)return null;const draft=session.draft,mode=session.mode,isAi=mode==='ai';if(isAi){for(const [key,label] of [['standard','성취기준'],['type','문항 유형'],['difficulty','난이도'],['idea','문항 핵심 아이디어']])if(!String(draft[key]||'').trim()){document.querySelector('#authoringDraftForm [data-authoring-field="'+key+'"]')?.focus();throw Error(label+'을(를) 입력해 주세요.')}if(Array.from(String(draft.materials_request||'')).length>4000){$('#authoringDraftForm [data-authoring-field="materials_request"]')?.focus();throw Error('필요한 자료 요청은 4000자 이내로 적어 주세요.')}}
 let cardId=session.committedCardId||session.targetCardId||session.reuseCardId,index=cardId?state.exam.cards.findIndex(card=>card.id===cardId):-1,card=index>=0?state.exam.cards[index]:null,isNew=!card;if(!card){card=authoringBlankCard(session.committedCardId||session.reuseCardId||(typeof uxMakeId==='function'?uxMakeId():crypto.randomUUID().replaceAll('-','').slice(0,16)),state.exam.cards.length+1);index=state.exam.cards.length;state.exam.cards.push(card)}const before=authoringProjection(card);
 for(const key of ['standard','standard_name','standard_note','type','difficulty','idea'])card[key]=draft[key]??'';card.authoring_mode=session.persistMode||mode;card.ai_requested=isAi;card.no=card.no||index+1;
 if(isAi){card.materials_request=String(draft.materials_request||'');card.material_request_kinds=authoringRequestKinds(draft);card.material_request_image_mode=authoringRequestImageModeDisabled(draft)?'':['','strict','mixed','flexible'].includes(draft.material_request_image_mode)?draft.material_request_image_mode:''}else{for(const key of ['stem','question','statements','choices','answer','concepts','explanation','calculation','checks','materials','data_kind','material'])if(key in draft)card[key]=structuredClone(draft[key]);card.ai_requested=false;if(typeof uxSyncMaterialAliases==='function'&&Array.isArray(card.materials))uxSyncMaterialAliases(card)}
 session.committedCardId=card.id;state.exam.cards[index]=card;state.card=index;session.contentChanged=isNew||JSON.stringify(before)!==JSON.stringify(authoringProjection(card));return card}
function authoringDraftError(){const session=state.authoringDraft;if(session?.mode!=='ai')return null;for(const [key,label] of [['standard','성취기준'],['type','문항 유형'],['difficulty','난이도'],['idea','문항 핵심 아이디어']])if(!String(session.draft?.[key]||'').trim())return {key,message:label+'을(를) 입력해 주세요.'};if(Array.from(String(session.draft?.materials_request||'')).length>4000)return {key:'materials_request',message:'필요한 자료 요청은 4000자 이내로 적어 주세요.'};return null}
async function authoringCommit(){const session=state.authoringDraft;if(!session||session.suspended)return;const invalid=authoringDraftError();if(invalid){document.querySelector('#authoringDraftForm [data-authoring-field="'+invalid.key+'"]')?.focus({preventScroll:true});toast(invalid.message);return}const before=structuredClone(state.exam),wasDirty=state.dirty,previousCard=state.card;try{const card=authoringApplyDraft();if(!card)return;markDirty(!!session.contentChanged);await save()}catch(error){state.exam=before;state.card=previousCard;state.dirty=wasDirty;if(typeof uxState!=='undefined'){if(uxState.conflict)uxState.conflict.local=structuredClone(before);if(typeof uxWriteDraft==='function')uxWriteDraft();uxSetSaveStatus(error.code==='revision_conflict'?'conflict':'failed')}session.failed=true;authoringPersistLocal();render();throw error}const mode=session.mode;state.authoringDraft=null;authoringClearLocal();state.stage=mode==='ai'?0:1;if(typeof uxState!=='undefined')uxState.tab='question';render();if(mode==='ai')toast('AI 생성 대기 목록에 저장했습니다. 문항 생성은 별도로 시작하세요.');else toast('문항 초안을 저장했습니다. 검토 단계에서 계속 편집할 수 있습니다.')}
document.addEventListener('input',event=>{if(typeof uxState!=='undefined')return;const form=event.target.closest('#authoringDraftForm'),session=state.authoringDraft;if(!form||!session)return;const field=event.target.closest('[data-authoring-field]');if(field){event.stopImmediatePropagation();const key=field.dataset.authoringField;session.draft[key]=field.value;authoringPersistLocal();if(key==='standard'){const found=state.standards[field.value];session.draft.standard_name=found?.name||'';session.draft.standard_note=found?.note||'';const note=form.querySelector('[data-authoring-standard-note]');if(note)note.textContent=found?.name||'성취기준을 선택해 주세요.'}if(key==='materials_request'){const count=form.querySelector('#materialsRequestCount');if(count)count.textContent=`${Array.from(field.value).length}/4000자`}return}const checks=event.target.closest('[data-authoring-checks]');if(checks){event.stopImmediatePropagation();session.draft.checks=checks.value.split('\n').filter(x=>x.trim()).map(line=>{const [label,lhs,rhs]=line.split('|').map(x=>x.trim());return {label:label||'',lhs:lhs||'',rhs:rhs||''}});authoringPersistLocal()}},true);
document.addEventListener('change',event=>{if(typeof uxState!=='undefined')return;const form=event.target.closest('#authoringDraftForm'),session=state.authoringDraft;if(!form||!session)return;const requestKind=event.target.closest('[data-authoring-request-kind]');if(requestKind){event.stopImmediatePropagation();authoringSetRequestKinds(session.draft,[...form.querySelectorAll('[data-authoring-request-kind]:checked')].map(input=>input.dataset.authoringRequestKind));authoringSyncRequestImageMode(form,session.draft);authoringPersistLocal();return}const bool=event.target.closest('[data-authoring-bool]');if(bool){event.stopImmediatePropagation();session.draft[bool.dataset.authoringBool]=bool.checked;authoringPersistLocal();return}const field=event.target.closest('[data-authoring-field]');if(field){event.stopImmediatePropagation();session.draft[field.dataset.authoringField]=field.value;authoringPersistLocal();if(field.dataset.authoringField==='standard'){const found=state.standards[field.value];session.draft.standard_name=found?.name||'';session.draft.standard_note=found?.note||'';const note=form.querySelector('[data-authoring-standard-note]');if(note)note.textContent=found?.name||'성취기준을 선택해 주세요.'}}},true);
$('#authoringChoiceDialog')?.addEventListener('cancel',event=>{event.preventDefault();authoringCancel()});
document.addEventListener('submit',event=>{if(event.target.id!=='authoringDraftForm')return;event.preventDefault();event.stopImmediatePropagation();action(authoringCommit)},true);
document.addEventListener('click',event=>{if(typeof uxState!=='undefined')return;if(event.target.closest('[data-authoring-resume]')){event.preventDefault();event.stopImmediatePropagation();if(state.authoringDraft){state.authoringDraft.suspended=false;authoringPersistLocal();render();requestAnimationFrame(()=>document.querySelector('#authoringDraftForm [data-authoring-field="standard"]')?.focus({preventScroll:true}))}return}if(event.target.closest('[data-authoring-discard]')){event.preventDefault();event.stopImmediatePropagation();authoringDiscard();return}const cancel=event.target.closest('[data-authoring-cancel]');if(cancel){event.preventDefault();event.stopImmediatePropagation();authoringCancel();return}const choice=event.target.closest('[data-authoring-choice]');if(choice){event.preventDefault();event.stopImmediatePropagation();authoringChoose(choice.dataset.authoringChoice);return}if(event.target.closest('#addCard')||event.target.closest('[data-ux-action="add-card"]')){event.preventDefault();event.stopImmediatePropagation();authoringOpenChoice();return}const row=event.target.closest('[data-card]');if(row&&state.exam&&state.stage===0&&!event.target.closest('[data-ai-request]')&&!event.target.closest('.row-more')){const selected=state.exam.cards[Number(row.dataset.card)],hasQuestion=String(selected?.question||'').trim(),mode=selected?.authoring_mode;if(selected&&(!hasQuestion&&authoringAiPending(selected)||mode==='manual'&&!hasQuestion)){event.preventDefault();event.stopImmediatePropagation();authoringStart(authoringAiPending(selected)?'ai':'manual',selected.id)}}},true);
let keyboardReorderId=null;
function designReorderHandle(card,index){const number=index+1,id=esc(card.id),keys='Space로 잡고 위·아래 화살표로 이동한 뒤 Space로 놓습니다. Esc로 취소합니다.';return `<span class="drag-handle design-reorder-handle" role="button" tabindex="0" data-reorder-handle="${id}" aria-pressed="${keyboardReorderId===card.id?'true':'false'}" aria-label="${number}번 문항 순서 변경. ${keys}" title="끌어서 이동 · 키보드: Space, ↑/↓, Space · Esc">⠿</span>`}
function designImageThumbs(card){let blocks=Array.isArray(card?.materials)?card.materials.filter(block=>block?.kind==='image'):[];if(!blocks.length&&card?.image)blocks=[{id:card.id,kind:'image',image:card.image,image_scene:card.image_scene}];const thumbs=blocks.map((block,index)=>{const image=block.image;if(!image)return '';const filename=image.approved&&image.final_file?image.final_file:(block.image_scene&&image.edited_file?image.edited_file:image.file);if(!filename)return '';const materialLabel=block.label||`자료 그림 ${index+1}`,title=`${card.no}번 문항 · ${materialLabel}`,src=`/assets/${encodeURIComponent(state.exam.id)}/${encodeURIComponent(filename)}`;return `<button class="design-thumbnail-button" type="button" data-image-preview data-preview-material-id="${esc(block.id||card.id)}" data-preview-src="${esc(src)}" data-preview-title="${esc(title)}" data-preview-alt="${esc(`${card.no}번 ${materialLabel}`)}" aria-label="${esc(`${title} 크게 보기`)}" title="${esc(`${materialLabel} 크게 보기`)}" draggable="false"><img class="design-thumbnail" src="${esc(src)}" alt="" draggable="false"></button>`}).filter(Boolean);return thumbs.length?`<span class="design-thumbnails">${thumbs.join('')}</span>`:''}
let designImagePreviewTrigger=null;
function showDesignImagePreview(button){const dialog=$('#designImagePreviewDialog'),image=$('#designImagePreviewImage');if(!dialog||!image||!button?.dataset.previewSrc)return;designImagePreviewTrigger=button;$('#designImagePreviewTitle').textContent=button.dataset.previewTitle||'자료 그림';image.src=button.dataset.previewSrc;image.alt=button.dataset.previewAlt||'자료 그림';dialog.showModal()}
const designImagePreviewDialog=$('#designImagePreviewDialog');
if(designImagePreviewDialog){
 designImagePreviewDialog.addEventListener('click',event=>{
  if(event.target.closest('[data-image-preview-close]')){designImagePreviewDialog.close();return}
  if(event.target===designImagePreviewDialog){const rect=designImagePreviewDialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)designImagePreviewDialog.close()}
 });
 designImagePreviewDialog.addEventListener('close',()=>{const image=$('#designImagePreviewImage');if(image){image.removeAttribute('src');image.alt=''}if(designImagePreviewTrigger?.isConnected)designImagePreviewTrigger.focus({preventScroll:true});designImagePreviewTrigger=null});
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-image-preview]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();showDesignImagePreview(button)},true);
function overview(){const e=state.exam,cs=e.cards;return `<div class="stats"><div class="stat"><span>전체 문항</span><strong>${cs.length}<small>문항</small></strong></div><div class="stat"><span>문항 검토 완료</span><strong>${cs.filter(c=>c.review_approved).length}<small>/ ${cs.length}</small></strong></div><div class="stat"><span>자료 그림 승인</span><strong>${cs.filter(c=>c.data_kind==='image'&&c.image?.approved).length}<small>/ ${cs.filter(c=>c.data_kind==='image').length}</small></strong></div><div class="stat"><span>총 배점</span><strong>${Number(cs.reduce((a,c)=>a+Number(c.points||0),0).toFixed(2))}<small>점</small></strong></div></div><div class="overview-grid"><section class="panel"><div class="panel-head"><div><h3>문항카드 목록</h3><small>실제 작성된 1~${cs.length}번 문항을 기준으로 출제합니다.</small></div><button class="small-btn" id="addCard">＋ 문항 추가</button></div><table class="card-table"><thead><tr><th>번호</th><th>핵심 아이디어 / 성취기준</th><th>유형 · 난이도</th><th>배점</th><th>정답 번호</th><th>AI 요청</th><th>상태</th></tr></thead><tbody>${cs.map((c,i)=>{const points=String(c.points??'').trim(),idea=String(c.idea||'핵심 아이디어를 입력해 주세요'),answer=answerNumber(c.answer),answerClass='①②③④⑤'.includes(answer)?' design-answer-number':'';return `<tr data-card="${i}" data-reorder="${esc(c.id)}" draggable="true"><td class="score design-number-cell">${designReorderHandle(c,i)}<span>${String(i+1).padStart(2,'0')}</span></td><td><div class="design-idea-cell"><span class="design-idea-text">${esc(idea)}</span>${designImageThumbs(c)}</div><small class="muted">${esc(c.standard||'성취기준 미입력')}</small></td><td>${esc(c.type||'유형 미선택')}<br><small class="muted">${esc(c.difficulty||'—')}</small></td><td><output class="design-readonly-value" aria-label="${i+1}번 배점">${points?`${esc(points)}점`:'미입력'}</output></td><td><output class="design-readonly-value${answerClass}" aria-label="${i+1}번 정답 번호">${esc(answer)}</output></td><td>${requestSelect(c)}</td><td>${badge(c)}</td></tr>`}).join('')}</tbody></table><p class="design-reorder-hint">순서 변경: 끌기 또는 ⠿에 초점을 두고 Space → ↑/↓ → Space · Esc로 취소</p><p id="reorderAnnounce" class="sr-only" aria-live="polite" aria-atomic="true"></p></section><aside><section class="panel"><div class="panel-body"><div class="eyebrow">WORKFLOW GUIDE</div><h2>이번 시험의 흐름</h2><ul class="note-list"><li><b>01　출제 의도를 먼저 정하세요</b>성취기준, 난이도, 유형, 배점과 핵심 아이디어를 입력합니다.</li><li><b>02　문항카드를 검토·승인하세요</b>CLI가 작성한 문항·해설·이미지 프롬프트와 100점 배점을 확인합니다.</li><li><b>03　승인 후 그림과 시험지를 만드세요</b>문항카드 전체 승인 후 실제 자료 그림을 제작하고 시험지로 옮깁니다.</li></ul><span class="badge">${esc(state.provider==='codex'?'Codex CLI':'Claude Code')} 연결</span></div></section><div class="help-card"><h3>원래의 양식 그대로</h3><p>단일 정답형 · 합답형 · 불완전 문장형 · 짝짓기형을 지원합니다. 문항 수와 상·중·하 난이도에 따라 합계 100점으로 배점합니다.</p></div></aside></div>`}
function rail(imageOnly=false){return `<div class="item-rail">${state.exam.cards.map((c,i)=>`<button class="item-btn ${i===state.card?'active':''}" data-select="${i}" data-reorder="${c.id}" draggable="true"><span class="drag-handle" title="끌어서 순서 변경">⠿</span><span class="circle">${String(i+1).padStart(2,'0')}</span>${imageOnly?(c.data_kind==='image'?'자료 그림':'그림 없음'):(c.type||'새 문항')}<small>${esc(c.idea||'아이디어 미입력')}</small></button>`).join('')}<button id="addCard" class="small-btn">＋ 문항 추가</button></div>`}
function field(key,label,opts={}){const c=current();if(key==='standard')return standardField(c);return `<label class="${opts.full?'full':''}">${label}${opts.select?`<select data-field="${key}">${opts.select.map(v=>`<option value="${esc(v)}" ${c[key]===v?'selected':''}>${esc(v||'선택해 주세요')}</option>`).join('')}</select>`:opts.textarea?`<textarea class="${opts.tall?'tall':''}" data-field="${key}" placeholder="${esc(opts.placeholder||'')}">${esc(c[key])}</textarea>`:`<input data-field="${key}" ${opts.list?'list="standards"':''} value="${esc(c[key])}" placeholder="${esc(opts.placeholder||'')}">`}</label>`}
function editor(){const c=current();return `<div class="edit-layout">${rail()}<section class="panel"><div class="panel-head"><div><h3>${c.no}번 문항 작성</h3><small>출제 의도와 생성된 문항을 함께 관리합니다.</small></div>${badge(c)}</div><div class="panel-body"><div class="fields">${field('standard','성취기준 코드',{list:true,placeholder:'예: [12역학01-01]'})}${field('difficulty','난이도',{select:['','하','중','상']})}${field('type','문항 유형',{select:['',...state.boot.types]})}${field('points','배점',{placeholder:'예: 4.2'})}<label class="full ai-request-field">AI 생성 요청${requestSelect(c)}<small>Yes 문항만 일괄 생성합니다. 저장 성공 후 No로 바뀝니다.</small></label>${field('idea','문항 핵심 아이디어',{full:true,textarea:true,placeholder:'물리 상황, 평가할 개념, 조건을 구체적으로 적어 주세요.'})}</div><p id="standardName" class="hint">${esc(c.standard_name)}</p><label>수정 요청 <span class="muted">선택 사항</span><textarea data-field="ai_feedback" class="feedback" placeholder="예: 상황은 유지하고 ㄷ 보기의 추론 단계를 늘려 주세요.">${esc(c.ai_feedback||'')}</textarea></label><div class="buttons-wrap section-title"><button class="secondary" id="markRequested">이 문항 AI 요청 Yes로</button><button class="small-btn danger" id="removeCard">문항 삭제</button></div><div class="sep"></div><h3>문항 구성</h3><div class="fields">${field('stem','문두',{full:true,textarea:true})}<label class="full">자료 종류<select data-field="data_kind">${[['none','자료 없음'],['image','그림 · 이미지 프롬프트'],['text','글상자'],['table','표 · 마크다운']].map(([v,l])=>`<option value="${v}" ${c.data_kind===v?'selected':''}>${l}</option>`).join('')}</select></label>${field('material','자료 / 이미지 프롬프트의 장면 설명',{full:true,textarea:true,tall:true})}<div class="full">${imagePlanFields(c)}</div>${field('question','발문',{full:true,textarea:true})}${field('statements','보기 · ㄱ, ㄴ, ㄷ',{full:true,textarea:true})}${field('choices','답지 · ①~⑤',{full:true,textarea:true,tall:true})}${field('answer','정답 번호 · 1~5')}${field('concepts','내용 영역')}${field('explanation','해설 및 오답 분석',{full:true,textarea:true,tall:true})}</div><label class="check-row"><input type="checkbox" data-bool="calculation" ${c.calculation?'checked':''}>계산이 포함된 문항</label><label>검산식 <span class="muted">한 줄에 이름 | 왼쪽 식 | 오른쪽 식</span><textarea id="checksInput" placeholder="속력 | 2*3 | 6">${esc(c.checks.map(x=>`${x.label} | ${x.lhs} | ${x.rhs}`).join('\n'))}</textarea></label><div class="buttons-wrap section-title"><button id="verify" class="small-btn">SymPy 검산</button><button id="approveQuestion" class="${c.review_approved?'secondary':'primary'}">${c.review_approved?'문항 검토 승인 취소':'문항 검토 완료'}</button></div><div id="checkResults"></div><p class="hint">검산은 제공된 등식의 일치를 확인합니다. 원문 상황·정답 대응·개념 타당성은 직접 확인해 주세요.</p><p class="image-notes">${esc(c.review_note)}</p></div></section><aside class="panel preview"><div class="preview-head"><span>문항 내용 미리보기</span><span>${String(c.no).padStart(2,'0')}</span></div><div id="previewSheet">${preview(c)}</div><div class="preview-footer">내용 확인용입니다. 수식·쪽 배치는 한글 출력에서 확인하세요.</div></aside></div>`}
function preview(c){const stem=String(c.stem||'').trim(),question=String(c.question||'').trim();return `<div class="sheet"><div class="sheet-title">${esc(state.exam.title)}</div><p class="preview-stem"><b>${c.no}.</b> ${stem?previewMathText(c.stem):'<span class="preview-empty-field">문두가 비어 있습니다.</span>'}</p>${c.data_kind==='image'?(c.image?`<img src="/assets/${state.exam.id}/${c.image.approved&&c.image.final_file?c.image.final_file:(c.image_scene?c.image.edited_file:c.image.file)}" alt="${c.no}번 자료 그림">`:'<div class="material-box muted">자료 그림 생성 대기</div>'):(c.material&&c.data_kind!=='none'?`<div class="material-box">${previewMathText(c.material)}</div>`:'')}<p class="preview-question">${question?previewMathText(c.question):'<span class="preview-empty-field">발문이 비어 있습니다.</span>'} ${c.points?`[${esc(c.points)}점]`:''}</p>${c.statements?`<div class="material-box">${previewMathText(c.statements)}</div>`:''}<div class="choice">${previewMathText(c.choices)}</div></div>`}
function exportsView(){const e=state.exam,v=e.validation||{errors:['검토 상태를 새로 확인해 주세요.'],warnings:[],ready:false};return `<div class="export-layout"><section class="panel"><div class="panel-head"><div><h3>출력 전 최종 점검</h3><small>승인되지 않은 문항·그림과 누락된 내용을 확인합니다.</small></div><span class="badge ${v.ready?'success':'warn'}">${v.ready?'출력 준비 완료':v.errors.length+'개 확인 필요'}</span></div><div class="panel-body">${v.errors.length?`<ul class="issues">${v.errors.map(x=>`<li>○ ${esc(x)}</li>`).join('')}</ul>`:'<div class="notice">✓ 문항 필수 정보, 문항 검토, 검산, 그림 승인 확인을 통과했습니다.</div>'}${v.warnings.map(x=>`<div class="notice warn">${esc(x)}</div>`).join('')}<div class="sep"></div><h3>학교 양식으로 내보내기</h3><p>시험지 학생용·교사용 HML, 정답과 해설, 문항카드 엑셀, 검수 기록을 함께 저장합니다.</p><div class="buttons-wrap section-title"><button class="primary" id="exportBtn" ${v.ready?'':'disabled'}>시험지 · 답지 파일 생성 →</button><button id="refreshValidation">검토 상태 새로고침</button></div><div class="notice warn">HML의 수식 크기와 실제 쪽 배치는 한글에서 최종 확인해 주세요. 한글·pyhwpx가 설치되어 있다면 아래 출력 묶음의 재계산 버튼을 사용할 수 있습니다.</div></div></section><aside><section class="panel"><div class="panel-head"><h3>출력 기록 <span class="muted">${e.exports.length}</span></h3></div><div class="panel-body">${e.exports.length?e.exports.slice().reverse().map(b=>`<div><h3>${esc(b.created.replace('T',' '))}</h3><p class="hint">문항 버전 ${b.revision} · 출력 후 수정 내용은 새로 출력해야 반영됩니다.</p>${b.files.map(name=>`<a class="download" href="/download/${e.id}/${b.id}/${encodeURIComponent(name)}"><span>${esc(name)}</span><small>↓</small></a>`).join('')}<button class="small-btn wide" data-recalc="${b.id}">한글 수식 재계산 → HWP</button><div class="sep"></div></div>`).join(''):'<div class="placeholder">완성된 시험지와 답지가<br>여기에 모입니다.</div>'}</div></section></aside></div>`}
function bindWorkspace(){const bind=(s,fn)=>{const el=$(s);if(el)el.onclick=()=>action(fn)};bind('#startWelcome',()=>$('#createDialog').showModal());bind('#saveBtn',async()=>{await save();toast('저장했습니다.')});bind('#runAll',()=>generate('question',false));bind('#generateAllImages',()=>generate('image',false));bind('#allocatePoints',async()=>{await save();state.exam=await api('/api/allocate',{exam_id:state.exam.id});render();toast('난이도에 따라 합계 100점으로 배점했습니다. 변경된 배점과 문항을 검토해 주세요.')});bind('#approveCards',async()=>{await save();state.exam=await api('/api/approve-cards',{exam_id:state.exam.id});state.stage=2;render();toast('문항카드를 승인했습니다. 이제 실제 자료 그림을 만들 수 있습니다.')});bind('#addCard',addCard);bind('#markRequested',async()=>{current().ai_requested=true;markDirty(false);await save();render();toast('AI 요청을 Yes로 설정했습니다. 상단 일괄 생성 버튼으로 실행하세요.')});bind('#deleteExam',()=>{if(state.job?.status==='running')throw Error('진행 중인 작업을 먼저 완료하거나 취소해 주세요.');$('#deleteTitle').textContent=state.exam.title;$('#deleteDialog').showModal()});bind('#confirmImagePlan',async()=>{await save();state.exam=await api('/api/confirm-image-plan',{exam_id:state.exam.id,card_id:current().id});render();toast('그림 유형과 제작 범위를 확인했습니다.')});bind('#generateImage',()=>generate('image'));bind('#removeCard',async()=>{if(state.exam.cards.length===1)throw Error('최소 한 문항은 남겨 주세요.');state.exam.cards.splice(state.card,1);state.card=Math.max(0,state.card-1);state.dirty=true;await save();render()});bind('#approveQuestion',()=>approve('question'));bind('#approveImage',()=>approve('image'));bind('#verify',async()=>{await save();const r=await api('/api/verify',{exam_id:state.exam.id,card_id:current().id});$('#checkResults').innerHTML=r.checks.length?r.checks.map(x=>`<div class="check-result ${x.ok?'':'fail'}">${esc(x.label)} · ${x.ok?'✓ 일치':esc(x.detail)}</div>`).join(''):'<p class="hint">검산식을 입력해 주세요.</p>';if(r.calculation?.override_allowed&&!r.calculation?.override_active){const approved=await approveWithDiscrepancy(current(),'question');if(approved){state.exam=approved;render()}}});bind('#uploadImage',()=>$('#imageUpload').click());bind('#openLibrary',async()=>{await save();const list=await api('/api/library');$('#libraryGrid').innerHTML=list.map(x=>`<button data-library="${esc(x.name)}"><img src="/library/${encodeURIComponent(x.name)}" alt="${esc(x.name)}">${esc(x.name)}</button>`).join('');$('#libraryDialog').showModal()});bind('#refreshValidation',async()=>{await save();state.exam=await api('/api/exams/'+state.exam.id);render()});bind('#exportBtn',async()=>{await save();$('#exportBtn').disabled=true;try{state.exam=await api('/api/export',{exam_id:state.exam.id});state.exam=await api('/api/exams/'+state.exam.id);toast('시험지와 답지를 생성했습니다.')}finally{render()}});
 document.querySelectorAll('[data-field]').forEach(el=>el.addEventListener('input',()=>{current()[el.dataset.field]=el.value;if(['image_mode','image_locked','image_creative','material','stem','question','choices','statements','data_kind'].includes(el.dataset.field))current().image_plan_approval=null;if(el.dataset.field==='image_mode'){if(el.value==='strict'){current().image_creative='';const free=$('[data-field=image_creative]');if(free)free.value=''}const hint=$('#imageModeHint');if(hint)hint.textContent=modeDescription(el.value)}markDirty(el.dataset.field!=='ai_feedback');if(el.dataset.field==='standard'){const found=state.standards[el.value];current().standard_name=found?.name||'';current().standard_note=found?.note||'';$('#standardName').textContent=found?.name||'성취기준 코드가 템플릿 목록에 있는지 확인해 주세요.'}if($('#previewSheet')){$('#previewSheet').innerHTML=preview(current());renderPreviewMath()}}));
 document.querySelectorAll('[data-bool]').forEach(el=>el.onchange=()=>{current()[el.dataset.bool]=el.checked;markDirty()});
 if($('#checksInput'))$('#checksInput').oninput=()=>{current().checks=$('#checksInput').value.split('\n').filter(x=>x.trim()).map(line=>{const [label,lhs,rhs]=line.split('|').map(x=>x.trim());return {label:label||'',lhs:lhs||'',rhs:rhs||''}});markDirty()};
}
function markDirty(contentChanged=true){state.dirty=true;if(contentChanged){state.exam.card_approval=null;current().review_approved=false;$('#approvalBar').innerHTML=approvalBar();bindApprovalAfterEdit();for(const id of ['generateImage','uploadImage','openLibrary','approveImage','confirmImagePlan']){const el=$('#'+id);if(el)el.disabled=true}}$('#saveState').textContent='저장하지 않은 변경';renderStats();}
function addCard(){authoringOpenChoice()}
async function approve(kind){await save();const c=current(),approved=kind==='image'?!c.image.approved:!c.review_approved;if(approved){const updated=await approveWithDiscrepancy(c,kind,c.materials?.find(block=>block.kind==='image'&&!block.image?.approved)?.id);if(!updated)return;state.exam=updated}else state.exam=await api('/api/approve',{exam_id:state.exam.id,card_id:c.id,kind,approved:false});render()}
async function generate(kind,single=true){const feedback=$('#feedback')?.value||'';await save();let cardIds;if(kind==='question'){cardIds=single?[current().id]:state.exam.cards.filter(c=>c.ai_requested&&authoringAiPending(c)).map(c=>c.id);if(!cardIds.length)throw Error('AI 생성 요청이 Yes인 문항이 없습니다.')}const job=await api('/api/jobs',{exam_id:state.exam.id,...(kind==='question'?{card_ids:cardIds}:{card_id:single?current().id:null}),action:kind,feedback,provider:state.provider,model:state.model});state.job=job;watch(job.id)}
function setBusy(busy){document.querySelectorAll('#approvalBar button,#workspace button,#workspace input,#workspace textarea,#workspace select,#topActions button,#steps button,.exam-list button,#newExam').forEach(el=>{if(busy){if(el.dataset.wasDisabled===undefined)el.dataset.wasDisabled=el.disabled;el.disabled=true}else{el.disabled=el.dataset.wasDisabled==='true';delete el.dataset.wasDisabled}})}
function jobUnit(job){return job?.action==='question'||job?.action==='workflow'?'문항':job?.action==='plan'?'그림 계획':job?.action==='labels'?'그림 글씨':'그림'}
function jobLog(job=state.job){if(!job)return;$('#jobLog').textContent=(job.failed?.length?job.failed.map(x=>`${x.no}번 실패: ${x.error}`).join('\n')+'\n\n':'')+(job.log||job.message||'작업 기록을 기다리고 있습니다.');$('#logDialog').showModal()}
function renderJobProgress(job=state.job,{reconnecting=false}={}){
 const dialog=$('#jobProgressDialog');if(!dialog||!job)return;
 $('#jobProgressTitle').textContent=reconnecting?'연결을 다시 확인하고 있습니다.':'AI 작업을 잠시 기다려 주세요.';
 $('#jobProgressDescription').textContent=job.message||'AI 작업을 진행하고 있습니다.';
 const progress=Math.max(0,Number(job.progress)||0),total=Math.max(0,Number(job.total)||0),bar=$('#jobProgressBar');
 bar.hidden=total===0;bar.max=Math.max(1,total);bar.value=Math.min(progress,Math.max(1,total));
 $('#jobProgressMeta').textContent=total?`${progress} / ${total} ${jobUnit(job)} · ${job.status==='running'?'실행 중':job.status}`:`${job.provider||'AI'} · 작업 상태 확인 중`;
 const failures=$('#jobProgressFailures');failures.hidden=!job.failed?.length;failures.innerHTML=job.failed?.length?`<b>실패 ${job.failed.length}개</b><ul>${job.failed.map(item=>`<li>${esc(item.no)}번 · ${esc(item.error)}</li>`).join('')}</ul>`:'';
 $('#jobReconnectNotice').hidden=!reconnecting;
 $('#jobProgressDismiss').hidden=!(reconnecting&&jobPollErrors>=3);$('#jobProgressDismissHelp').hidden=!(reconnecting&&jobPollErrors>=3);
 const cancel=$('#jobProgressCancel');cancel.disabled=job.status!=='running'||jobCancelRequestedId===job.id;cancel.textContent=jobCancelRequestedId===job.id?'취소 요청됨':'생성 취소';
}
function renderJobBanner(job=state.job,{reconnecting=false}={}){
 const banner=$('#jobBanner');if(!banner||!job)return;
 banner.dataset.status=reconnecting?'reconnecting':job.status;
 if(job.status==='running'){
  banner.hidden=!jobProgressDismissed;
  if(!jobProgressDismissed)return;
  const text=reconnecting?'연결을 확인하지 못해 생성 상태를 다시 조회하고 있습니다. 완료 여부는 아직 확인되지 않았습니다.':job.message||'AI 작업을 진행하고 있습니다.';
  const detail=`${job.provider||'AI'} · ${Math.max(0,Number(job.progress)||0)} / ${Math.max(0,Number(job.total)||0)} ${jobUnit(job)} · 생성 중`;
  banner.innerHTML=`<div><b>${esc(text)}</b><small>${esc(detail)}</small></div><div class="buttons-wrap"><button type="button" class="small-btn" id="openJobProgress">상태 창 열기</button><button type="button" class="small-btn" id="cancelJob">작업 취소</button></div>`;
  $('#openJobProgress').onclick=()=>{jobProgressDismissed=false;renderJobProgress(state.job,{reconnecting:jobPollErrors>0});if(!$('#jobProgressDialog').open)$('#jobProgressDialog').showModal();renderJobBanner(state.job,{reconnecting:jobPollErrors>0})};
  $('#cancelJob').onclick=()=>requestJobCancel(job.id);
  return;
 }
 banner.hidden=job.status==='completed'&&new URLSearchParams(location.search).get('ux')!=='old';
 banner.innerHTML=`<div><b>${esc(job.message||'작업이 종료되었습니다.')}</b><small>${esc(job.provider||'AI')} · ${Math.max(0,Number(job.progress)||0)} / ${Math.max(0,Number(job.total)||0)} ${jobUnit(job)}</small>${job.failed?.length?`<details class="job-failures"><summary>실패 ${job.failed.length}개 이유</summary><ul>${job.failed.map(x=>`<li>${esc(x.no)}번 · ${esc(x.error)}</li>`).join('')}</ul></details>`:''}</div><div class="buttons-wrap"><button type="button" class="small-btn" id="showLog">작업 기록</button><button type="button" class="small-btn" id="closeJob">닫기</button></div>`;
 $('#showLog').onclick=()=>jobLog(job);$('#closeJob').onclick=()=>{banner.hidden=true;state.job=null};
}
let jobCancelRequestedId=null;
async function requestJobCancel(id){if(!id||state.job?.status!=='running')return;const cancel=$('#jobProgressCancel');if(cancel)cancel.disabled=true;try{await api('/api/cancel',{job_id:id});jobCancelRequestedId=id;if(jobWatchId===id)renderJobProgress(state.job,{reconnecting:jobPollErrors>0});toast('취소를 요청했습니다.')}catch(error){toast(error.message);if(jobWatchId===id)renderJobProgress(state.job,{reconnecting:jobPollErrors>0})}}
const jobProgressDialog=$('#jobProgressDialog');
jobProgressDialog?.addEventListener('cancel',event=>{if(state.job?.status==='running')event.preventDefault()});
jobProgressDialog?.addEventListener('click',event=>{if(event.target===jobProgressDialog&&state.job?.status==='running')event.preventDefault()});
$('#jobProgressLog')?.addEventListener('click',()=>jobLog());
$('#jobProgressCancel')?.addEventListener('click',()=>requestJobCancel(jobWatchId));
$('#jobProgressDismiss')?.addEventListener('click',()=>{if(jobPollErrors<3||state.job?.status!=='running')return;jobProgressDismissed=true;jobProgressDialog.close('dismissed');renderJobBanner(state.job,{reconnecting:true})});
function watch(id){
 const jobId=String(typeof id==='object'?id?.id||'':id||'');if(!jobId)return;
 if(jobWatchId===jobId){if(state.job?.status==='running'&&!jobProgressDismissed){renderJobProgress(state.job,{reconnecting:jobPollErrors>0});if(!jobProgressDialog?.open)jobProgressDialog?.showModal()}return}
 clearTimeout(pollTimer);jobWatchId=jobId;const token=++jobWatchToken;jobPollErrors=0;jobProgressDismissed=false;jobCancelRequestedId=null;
 if(state.job?.id!==jobId)state.job={id:jobId,exam_id:state.exam?.id,status:'running',progress:0,total:0,message:'AI 생성 상태를 확인하고 있습니다.',provider:state.provider,action:''};
 setBusy(true);renderJobProgress(state.job);if(!jobProgressDialog?.open)jobProgressDialog?.showModal();renderJobBanner(state.job);
 async function tick(){
  if(token!==jobWatchToken||jobWatchId!==jobId)return;
  try{
   const job=await api('/api/jobs/'+encodeURIComponent(jobId));if(token!==jobWatchToken||jobWatchId!==jobId)return;
   const refresh=state.exam?.id===job.exam_id&&(job.status!=='running'||state.job?.progress!==job.progress);
   const exam=refresh?await api('/api/exams/'+job.exam_id):null;if(token!==jobWatchToken||jobWatchId!==jobId)return;
   jobPollErrors=0;state.job=job;
   if(job.status!=='running'){setBusy(false);jobCancelRequestedId=null;if(jobProgressDialog?.open)jobProgressDialog.close();jobProgressDismissed=false}
   if(exam){state.exam=exam;state.dirty=false;if(typeof uxBaseExam!=='undefined')uxBaseExam.value=JSON.parse(JSON.stringify(exam));render()}else if(job.status==='running')setBusy(true);
   renderJobProgress(job);renderJobBanner(job);
   if(job.status==='running')pollTimer=setTimeout(tick,1800);
   else if(job.status==='completed'&&!job.failed?.length&&$('#uxJobChip')){clearTimeout(toastTimer);$('#toast').hidden=true}
   else toast(job.message||'AI 작업이 종료되었습니다.');
  }catch(error){if(token!==jobWatchToken||jobWatchId!==jobId)return;jobPollErrors++;renderJobProgress(state.job,{reconnecting:true});renderJobBanner(state.job,{reconnecting:true});pollTimer=setTimeout(tick,5000)}
 }
 tick();
}
document.addEventListener('click',event=>{if(event.target.closest('[data-ai-request],[data-reorder-handle]'))return;const el=event.target.closest('button,tr');if(!el)return;action(async()=>{if(el.dataset.close)$('#'+el.dataset.close).close();if(el.dataset.exam)await openExam(el.dataset.exam);if(el.dataset.stage!==undefined){await save();state.stage=Number(el.dataset.stage);if(state.stage===3)state.exam=await api('/api/exams/'+state.exam.id);render()}if(el.dataset.card!==undefined||el.dataset.select!==undefined){await save();state.card=Number(el.dataset.card??el.dataset.select);if(el.dataset.card!==undefined)state.stage=1;render()}if(el.dataset.library){state.exam=await api('/api/image',{exam_id:state.exam.id,card_id:current().id,library:el.dataset.library});$('#libraryDialog').close();render()}if(el.dataset.recalc){el.disabled=true;try{state.exam=await api('/api/recalculate',{exam_id:state.exam.id,export_id:el.dataset.recalc});toast('한글 수식 재계산을 완료했습니다.')}finally{state.exam=await api('/api/exams/'+state.exam.id);render()}}})});
$('#newExam').onclick=()=>action(async()=>{await save();$('#createDialog').showModal()});
$('#createForm').elements.source.onchange=e=>$('#uploadLabel').hidden=e.target.value!=='upload';
async function file64(file){const bytes=new Uint8Array(await file.arrayBuffer());let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(str)}
$('#createForm').onsubmit=e=>{e.preventDefault();action(async()=>{const f=e.target,source=f.elements.source.value,data={title:f.elements.title.value,subject:f.elements.subject.value};if(source==='upload'){const file=f.elements.xlsx.files[0];if(!file)throw Error('엑셀 파일을 선택해 주세요.');data.xlsx=await file64(file)}if(source.startsWith('legacy:'))data.legacy=state.boot.legacy[Number(source.split(':')[1])];state.exam=await api('/api/create',data);state.authoringDraft=null;state.authoringChoiceBackup=null;state.card=0;state.stage=0;state.dirty=false;state.boot=await api('/api/bootstrap');$('#createDialog').close();f.reset();$('#uploadLabel').hidden=true;renderSidebar();render()})};
$('#settingsBtn').onclick=()=>{$('#provider').value=state.provider;$('#model').value=state.model;settingsStatus();$('#settingsDialog').showModal()};
function settingsStatus(){const p=$('#provider').value;$('#cliStatus').textContent=state.boot.cli[p]?'✓ CLI를 찾았습니다. 생성 시 기존 로그인 상태를 사용합니다.':'CLI가 감지되지 않았습니다. 설치·로그인 후 앱을 다시 시작해 주세요.'}
$('#provider').onchange=settingsStatus;
$('#saveSettings').onclick=()=>{state.provider=$('#provider').value;state.model=$('#model').value.trim();localStorage.setItem('qm-provider',state.provider);localStorage.setItem('qm-model',state.model);$('#settingsDialog').close();render();toast('CLI 설정을 저장했습니다.')};
$('#imageUpload').onchange=()=>action(async()=>{const file=$('#imageUpload').files[0];if(!file)return;await save();state.exam=await api('/api/image',{exam_id:state.exam.id,card_id:current().id,image:await file64(file)});$('#imageUpload').value='';render()});
window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue=''}});

$('#confirmDelete').onclick=()=>action(async()=>{const exam=state.exam;await api('/api/delete',{exam_id:exam.id,confirm_title:exam.title});$('#deleteDialog').close();clearTimeout(pollTimer);state.exam=null;state.job=null;state.dirty=false;$('#jobBanner').hidden=true;state.boot=await api('/api/bootstrap');renderSidebar();render();toast('작업실을 삭제했습니다. 원본은 프로젝트 휴지통에 보관됩니다.')});
document.addEventListener('change',event=>{const el=event.target.closest('[data-ai-request]');if(!el)return;const c=state.exam.cards.find(c=>c.id===el.dataset.aiRequest);if(c){c.ai_requested=el.value==='yes';markDirty(false)}});
function bindApprovalAfterEdit(){const bind=(id,fn)=>{const el=$('#'+id);if(el)el.onclick=()=>action(fn)};bind('allocatePoints',async()=>{await save();state.exam=await api('/api/allocate',{exam_id:state.exam.id});render()});bind('approveCards',async()=>{await save();state.exam=await api('/api/approve-cards',{exam_id:state.exam.id});state.stage=2;render()})}
function subjectLabel(){return state.boot.subjects.find(s=>s.id===state.exam?.subject)?.name||'과목 미지정'}
function standardField(c){const options=Object.entries(state.standards).filter(([,v])=>v.subject===state.exam.subject);return `<label>성취기준 · ${esc(subjectLabel())}<select data-field="standard"><option value="">성취기준을 선택해 주세요</option>${c.standard&&!options.some(([code])=>code===c.standard)?`<option selected value="${esc(c.standard)}">${esc(c.standard)} · 과목 확인 필요</option>`:''}${options.map(([code,v])=>`<option value="${esc(code)}" ${code===c.standard?'selected':''}>${esc(code)} ${esc(v.name)}</option>`).join('')}</select></label>`}
function requestSelect(c){return `<select data-ai-request="${c.id}" aria-label="${c.no}번 AI 생성 요청"><option value="no" ${!c.ai_requested?'selected':''}>No</option><option value="yes" ${c.ai_requested?'selected':''}>Yes</option></select>`}
function renderStats(){const el=$('#liveStats');el.hidden=!state.exam;if(!state.exam)return;const cards=state.exam.cards,count=(key,v)=>cards.filter(c=>c[key]===v).length;const chip=(label,n)=>`<span class="count-chip">${esc(label)} <b>${n}</b></span>`;const group=(label,values)=>`<div class="count-group"><strong>${label}</strong>${values}</div>`;const answer=c=>{const a=String(c.answer||'').trim();return '①②③④⑤'.includes(a)&&a?'①②③④⑤'.indexOf(a)+1:Number(a)};const standards={};for(const c of cards)standards[c.standard||'미입력']=(standards[c.standard||'미입력']||0)+1;el.innerHTML=`<div class="counts-top"><b>${esc(subjectLabel())} · 현재 <span id="totalCount">${cards.length}</span>문항</b><span>AI 요청 Yes <b id="aiYesCount">${count('ai_requested',true)}</b> · 총 ${Number(cards.reduce((s,c)=>s+(Number(c.points)||0),0).toFixed(2))}점</span></div><div class="counts-grid">${group('문항 유형',state.boot.types.map(t=>chip(t,count('type',t))).join('')+chip('미선택',count('type','')))}${group('난이도',['상','중','하'].map(t=>chip(t,count('difficulty',t))).join('')+chip('미선택',count('difficulty','')))}${group('정답',[1,2,3,4,5].map(n=>chip(n,cards.filter(c=>answer(c)===n).length)).join('')+chip('미입력',cards.filter(c=>!answer(c)).length))}</div><div class="count-group standard-counts"><strong>성취기준</strong><div>${Object.entries(state.standards).filter(([,v])=>v.subject===state.exam.subject).map(([code,v])=>`<span title="${esc(v.name)}">${chip(code,standards[code]||0)}</span>`).join('')}${Object.entries(standards).filter(([code])=>!state.standards[code]||state.standards[code].subject!==state.exam.subject).map(([code,n])=>chip(code,n)).join('')}</div></div>`;document.documentElement.style.setProperty('--stats-height',`${el.offsetHeight+16}px`)}
function announceReorder(message){const node=$('#reorderAnnounce');if(node)node.textContent=message}
function setKeyboardReorder(id,message){keyboardReorderId=id;document.querySelectorAll('[data-reorder-handle]').forEach(handle=>handle.setAttribute('aria-pressed',handle.dataset.reorderHandle===id?'true':'false'));if(message)announceReorder(message)}
async function reorderCards(source,target){if(source===target)return;if(state.job?.status==='running')throw Error('생성이 끝난 뒤 순서를 변경해 주세요.');await save();const old=state.exam.cards.slice(),active=current().id,from=old.findIndex(c=>c.id===source),to=old.findIndex(c=>c.id===target);if(from<0||to<0)return;const cards=old.slice();cards.splice(to,0,cards.splice(from,1)[0]);state.exam.cards=cards.map((c,i)=>({...c,no:i+1}));state.card=state.exam.cards.findIndex(c=>c.id===active);state.dirty=true;try{await save();render();const moved=state.exam.cards.find(c=>c.id===source);announceReorder(`${moved?.no||''}번 문항 순서를 저장했습니다.`);toast('문항 순서를 저장하고 번호를 다시 매겼습니다.')}catch(e){state.exam.cards=old;state.card=old.findIndex(c=>c.id===active);state.dirty=false;render();throw e}}
function bindReorder(){let dragging=null;document.querySelectorAll('[data-reorder]').forEach(el=>{el.addEventListener('dragstart',e=>{if(state.job?.status==='running'||e.target.closest('input,select,textarea,[data-image-preview]')){e.preventDefault();return}dragging=el.dataset.reorder;e.dataTransfer.setData('text/plain',dragging);e.dataTransfer.effectAllowed='move';el.classList.add('dragging')});el.addEventListener('dragover',e=>{if(dragging&&dragging!==el.dataset.reorder){e.preventDefault();e.dataTransfer.dropEffect='move';el.classList.add('drop-target')}});el.addEventListener('dragleave',()=>el.classList.remove('drop-target'));el.addEventListener('drop',e=>{e.preventDefault();el.classList.remove('drop-target');const source=dragging;dragging=null;if(source)action(()=>reorderCards(source,el.dataset.reorder))});el.addEventListener('dragend',()=>{dragging=null;document.querySelectorAll('.dragging,.drop-target').forEach(n=>n.classList.remove('dragging','drop-target'))})});document.querySelectorAll('[data-reorder-handle]').forEach(handle=>handle.addEventListener('keydown',event=>{const id=handle.dataset.reorderHandle;if(event.key===' '||event.key==='Enter'){event.preventDefault();const card=state.exam?.cards.find(item=>item.id===id);if(keyboardReorderId===id){setKeyboardReorder(null,`${card?.no||''}번 문항 순서 변경을 마쳤습니다.`)}else{setKeyboardReorder(id,`${card?.no||''}번 문항을 선택했습니다. 위쪽 또는 아래쪽 화살표로 옮기고 스페이스로 놓으세요.`)}return}if(event.key==='Escape'&&keyboardReorderId===id){event.preventDefault();setKeyboardReorder(null,`${state.exam?.cards.find(item=>item.id===id)?.no||''}번 문항 순서 변경을 취소했습니다.`);return}if(!['ArrowUp','ArrowDown'].includes(event.key)||keyboardReorderId!==id)return;event.preventDefault();if(state.job?.status==='running'){announceReorder('생성 작업이 끝난 뒤 순서를 바꿀 수 있습니다.');return}const index=state.exam.cards.findIndex(item=>item.id===id),targetIndex=index+(event.key==='ArrowUp'?-1:1);if(targetIndex<0||targetIndex>=state.exam.cards.length){announceReorder(event.key==='ArrowUp'?'첫 문항입니다.':'마지막 문항입니다.');return}const targetId=state.exam.cards[targetIndex].id;action(async()=>{await reorderCards(id,targetId);setKeyboardReorder(id,`${state.exam.cards.find(item=>item.id===id)?.no||''}번 문항으로 이동했습니다. 계속 이동하거나 스페이스로 놓으세요.`);[...document.querySelectorAll('[data-reorder-handle]')].find(item=>item.dataset.reorderHandle===id)?.focus()})}))}
